"""Display the last prompt generated by a request from the UI."""

import json
import os
from pathlib import Path
import sys


# Allow running this file directly from the repository root or from esperto/.
SRC_DIR = Path(__file__).resolve().parents[1]
if str(SRC_DIR) not in sys.path:
	sys.path.insert(0, str(SRC_DIR))

DEFAULT_PROMPT_FILE = Path(
	os.environ.get(
		"PROMPT_DEBUG_FILE",
		str(Path(__file__).resolve().parents[3] / "esperto_debug" / "last_prompt.json"),
	)
)


def main() -> None:
	prompt_path = Path(sys.argv[1]) if len(sys.argv) > 1 else DEFAULT_PROMPT_FILE
	if not prompt_path.exists():
		print(f"Nessun prompt salvato: {prompt_path}")
		print("Fai prima una domanda dalla UI e riprova.")
		return

	payload = json.loads(prompt_path.read_text(encoding="utf-8"))

	print("\n" + "=" * 80)
	print(f"ULTIMO PROMPT USATO DALLA UI: {prompt_path}")
	print("=" * 80)
	for index, message in enumerate(payload["messages"], start=1):
		print(f"\n--- MESSAGGIO {index} | ROLE: {message['role']} ---")
		print(message["content"])
	print("\n" + "=" * 80)


if __name__ == "__main__":
	main()
